import assert from "node:assert/strict";
import { join } from "node:path";
import test from "node:test";
import { AppArguments } from "@eyeauras/cli-factory";
import { createTeamCityCli } from "../src/cli.js";
import { createTestRuntime } from "./support.js";

test("missing nested TeamCity argument returns RPC error without ending the session", async () => {
  const input = [
    ["jobs", "show"],
    ["jobs", "show", "--help"],
  ].map((argv, index) => JSON.stringify({
    jsonrpc: "2.0", id: index + 1, method: "cli.execute", params: { argv },
  })).join("\n") + "\n";
  const runtime = await createTestRuntime({
    profiles: [{ name: "default", url: "https://teamcity.test", guest: true }],
    tokens: {},
    input,
  });
  runtime.runtime.appArguments = new AppArguments({
    AppName: "teamcity-cli",
    Profile: "default",
    Environment: {
      AppDomainDirectory: join("synthetic", "app"),
      ApplicationExecutablePath: join("synthetic", "app", "teamcity-cli.js"),
      EnvironmentLocalAppData: join("synthetic", "local"),
      EnvironmentAppData: join("synthetic", "roaming"),
      ProcessId: 42,
    },
  });
  let fetchCalls = 0;
  runtime.runtime.fetch = async () => {
    fetchCalls++;
    assert.fail("Argument errors and help must not call TeamCity.");
  };

  assert.equal(await createTeamCityCli(runtime.runtime).run(["--json-rpc"]), 0);
  const frames = runtime.stdout().trim().split("\n").map((line) => JSON.parse(line));
  assert.equal(frames.length, 2);
  assert.equal(frames[0].jsonrpc, "2.0");
  assert.equal(frames[0].id, 1);
  assert.equal(frames[0].error.code, -32000);
  assert.match(frames[0].error.message, /missing required argument 'id'/);
  assert.equal(frames[1].jsonrpc, "2.0");
  assert.equal(frames[1].id, 2);
  assert.match(frames[1].result.help, /Usage: teamcity-cli jobs show/);
  assert.equal(runtime.stderr(), "");
  assert.equal(fetchCalls, 0);
});

import assert from "node:assert/strict";
import test from "node:test";
import { Permission } from "@eyeauras/cli-factory";
import { http, HttpResponse } from "msw";
import { setupServer } from "msw/node";
import { createTeamCityCli } from "../src/cli.js";
import { createTestRuntime } from "./support.js";

const server = setupServer();

test.before(() => server.listen({ onUnhandledRequest: "error" }));
test.afterEach(() => server.resetHandlers());
test.after(() => server.close());

test("exposes the complete recursive tree and permission in leaf help", async () => {
  const testRuntime = await createTestRuntime();
  const cli = createTeamCityCli(testRuntime.runtime);

  assert.equal(await cli.run([]), 0);
  for (const branch of ["server", "projects", "jobs", "builds", "queue", "agents"]) {
    assert.match(testRuntime.stdout(), new RegExp(`\\b${branch}\\b`));
  }

  for (const [branch, leaf] of [
    ["server", "status"],
    ["projects", "list"],
    ["jobs", "run"],
    ["builds", "tests"],
    ["queue", "cancel"],
    ["agents", "show"],
  ] as const) {
    testRuntime.resetOutput();
    assert.equal(await cli.run([branch]), 0);
    assert.match(testRuntime.stdout(), new RegExp(`\\b${leaf}\\b`));
  }

  testRuntime.resetOutput();
  assert.equal(await cli.run(["jobs", "run", "--help"]), 0);
  assert.match(testRuntime.stdout(), /Required permission: Update/);
});

test("renders representative values for every read branch in human and JSON modes", async () => {
  server.use(
    http.get("https://teamcity.test/app/rest/server", () =>
      HttpResponse.json({
        version: "2026.1.3",
        versionMajor: 2026,
        versionMinor: 1,
        buildNumber: "222742",
        startTime: "fixture-start",
        currentTime: "fixture-now",
        role: "main_node",
        webUrl: "https://teamcity.test",
      }),
    ),
    http.get("https://teamcity.test/app/rest/projects", () =>
      HttpResponse.json({ project: [{ id: "Example", name: "Example", archived: false }] }),
    ),
    http.get("https://teamcity.test/app/rest/buildTypes", () =>
      HttpResponse.json({
        buildType: [
          {
            id: "Example_Build",
            name: "Build",
            projectId: "Example",
            projectName: "Example",
            paused: false,
          },
        ],
      }),
    ),
    http.get("https://teamcity.test/app/rest/builds", () =>
      HttpResponse.json({ build: [{ id: 101, state: "finished", status: "SUCCESS" }] }),
    ),
    http.get("https://teamcity.test/app/rest/buildQueue", () =>
      HttpResponse.json({ build: [{ id: 201, state: "queued", queuePosition: 1 }] }),
    ),
    http.get("https://teamcity.test/app/rest/agents", () =>
      HttpResponse.json({
        agent: [
          {
            id: 8,
            name: "fixture-agent",
            connected: true,
            enabled: true,
            authorized: true,
          },
        ],
      }),
    ),
  );

  const paths = [
    ["server", "status"],
    ["projects", "list"],
    ["jobs", "list"],
    ["builds", "list"],
    ["queue", "list"],
    ["agents", "list"],
  ];

  for (const path of paths) {
    const humanRuntime = await createTestRuntime();
    assert.equal(await createTeamCityCli(humanRuntime.runtime).run(path), 0);
    assert.notEqual(humanRuntime.stdout().trim(), "");
    assert.equal(humanRuntime.stderr(), "");

