test("cancels running and queued builds with metadata-preserving POSTs", async () => {
  server.use(
    http.post(`${baseUrl}/app/rest/builds/id:101`, async ({ request }) => {
      const url = assertAuthorization(request);
      assert.equal(url.searchParams.get("fields"), buildFields);
      assert.deepEqual(await request.json(), {
        comment: "Fixture cancellation",
        readdIntoQueue: false,
      });
      return HttpResponse.json({ id: 101, state: "finished", status: "UNKNOWN" });
    }),
    http.post(`${baseUrl}/app/rest/buildQueue/id:201`, async ({ request }) => {
      const url = assertAuthorization(request);
      assert.equal(url.searchParams.get("fields"), buildFields);
      assert.deepEqual(await request.json(), { readdIntoQueue: false });
      return HttpResponse.json({ id: 201, state: "finished", status: "UNKNOWN" });
    }),
  );

  assert.equal(
    (await client().cancelBuild(101, { comment: "Fixture cancellation" })).id,
    101,
  );
  assert.equal((await client().cancelQueuedBuild(201)).id, 201);
});

test("surfaces a remote mutation rejection without the token", async () => {
  server.use(
    http.post(`${baseUrl}/app/rest/builds/id:101`, () =>
      new HttpResponse("Build is already finished", { status: 409 }),
    ),
  );

  await assert.rejects(
    client().cancelBuild(101),
    (error: unknown) =>
      error instanceof TeamCityHttpError &&
      error.status === 409 &&
      error.message.includes("already finished") &&
      !error.message.includes("fixture-token"),
  );
});

import assert from "node:assert/strict";
import test from "node:test";
import {
  assertLocalProofEnvironment,
  formatProofReport,
  parseProofOptions,
  runProfileProof,
  type CliInvocation,
  type CliInvocationResult,
} from "../integration-tests/profile-proof.js";

test("profile proof accepts only an explicit profile", () => {
  assert.deepEqual(parseProofOptions(["--profile", "default"]), { profile: "default" });
  assert.throws(() => parseProofOptions([]), /Usage/);
  assert.throws(() => parseProofOptions(["--profile", "default", "jobs", "run"]), /Usage/);
  assert.throws(() => parseProofOptions(["--profile", "../escape"]), /invalid/);
});

test("profile proof refuses CI before invoking the CLI", async () => {
  let invocations = 0;
  await assert.rejects(
    runProfileProof(
      { profile: "default" },
      {
        environment: { CI: "true" },
        invoke: async () => {
          invocations += 1;
          throw new Error("must not run");
        },
      },
    ),
    /local-only/,
  );
  assert.equal(invocations, 0);
  assert.throws(() => assertLocalProofEnvironment({ GITHUB_ACTIONS: "true" }), /local-only/);
});

function json(value: unknown): CliInvocationResult {
  return { exitCode: 0, stdout: JSON.stringify(value), stderr: "" };
}

test("profile proof uses a fixed bounded read-only inventory and safe summaries", async () => {
  const invocations: CliInvocation[] = [];
  const privateValues = {
    project: "private-project-id",
    job: "private-job-id",
    build: 4242,
    agent: 73,
  };
  const invoke = async (invocation: CliInvocation): Promise<CliInvocationResult> => {
    invocations.push(invocation);
    if (invocation.argv[0] === "--json-rpc") {
      return {
        exitCode: 0,
        stdout:
          '{"jsonrpc":"2.0","id":1,"result":{"version":"private"}}\n' +
          '{"jsonrpc":"2.0","id":2,"result":[]}\n',
        stderr: "",
      };
    }
    const command = invocation.argv.slice(0, -3).join(" ");
    if (command === "permissions list") {
      return json([
        { name: "ReadOnly", enabled: true },
        { name: "Update", enabled: true },
      ]);
    }
    if (command === "auth status") return json({ authenticated: true, identity: { token: "secret" } });
    if (command === "server status") return json({ version: "private-version" });
    if (command === "projects list --limit 3") return json([{ id: privateValues.project }]);
    if (command === "jobs list --limit 3") return json([{ id: privateValues.job }]);
    if (command === "builds list --limit 3") return json([{ id: privateValues.build }]);
    if (command === "queue list --limit 3") return json([]);
    if (command === "agents list --limit 3") return json([{ id: privateValues.agent }]);
    if (command.startsWith("builds tests")) return json([]);
    if (command.startsWith("builds problems")) return json([]);
    if (command.startsWith("builds changes")) return json([]);
    return json({ ok: true, url: "https://private.example.test" });
  };

  const report = await runProfileProof(
    { profile: "default" },
    { environment: {}, invoke },
  );
  assert.equal(report.success, true);
  assert.equal(invocations.length, 17);
  assert.deepEqual(
    invocations.slice(0, -1).map((invocation) => invocation.argv.slice(0, -3)),
    [
      ["permissions", "list"],
      ["auth", "status"],
      ["server", "status"],
      ["projects", "list", "--limit", "3"],
      ["projects", "show", privateValues.project],
      ["jobs", "list", "--limit", "3"],
      ["jobs", "show", privateValues.job],
      ["jobs", "status", privateValues.job],
      ["builds", "list", "--limit", "3"],
      ["builds", "show", String(privateValues.build)],
      ["builds", "tests", String(privateValues.build), "--limit", "3"],
      ["builds", "problems", String(privateValues.build), "--limit", "3"],
      ["builds", "changes", String(privateValues.build), "--limit", "3"],
      ["queue", "list", "--limit", "3"],
      ["agents", "list", "--limit", "3"],
      ["agents", "show", String(privateValues.agent)],
    ],
  );
  for (const invocation of invocations.slice(0, -1)) {
    assert.deepEqual(invocation.argv.slice(-3), ["--profile", "default", "--json"]);
    assert.equal(invocation.argv.includes("run"), false);
    assert.equal(invocation.argv.includes("cancel"), false);
  }
  assert.deepEqual(invocations.at(-1)?.argv, ["--json-rpc"]);

  const output = formatProofReport(report);
  assert.match(output, /Summary: 17 passed, 0 skipped, 0 failed/);
  for (const privateValue of [
    ...Object.values(privateValues).map(String),
    "private-version",
    "private.example.test",
    "secret",
  ]) {
    assert.equal(output.includes(privateValue), false);
  }
});

test("profile proof treats empty pages as safe dependent skips", async () => {
  const invoke = async (invocation: CliInvocation): Promise<CliInvocationResult> => {
    if (invocation.argv[0] === "--json-rpc") {
      return {
        exitCode: 0,
        stdout: '{"jsonrpc":"2.0","id":1,"result":{"version":"version"}}\n{"jsonrpc":"2.0","id":2,"result":[]}\n',
        stderr: "",
      };
    }
    const command = invocation.argv.slice(0, -3).join(" ");
    if (command === "permissions list") return json([{ name: "ReadOnly", enabled: true }]);
    if (command === "auth status") return json({ authenticated: true });
    if (command === "server status") return json({ version: "version" });
    return json([]);
  };

  const report = await runProfileProof(
    { profile: "empty" },
    { environment: {}, invoke },
  );
  assert.equal(report.success, true);
  assert.equal(report.entries.filter((entry) => entry.status === "skipped").length, 8);
});

test("profile proof never copies failed CLI output into its report", async () => {
  const report = await runProfileProof(
    { profile: "default" },
    {
      environment: {},
      invoke: async () => ({
        exitCode: 1,
        stdout: '{"token":"secret-value","id":"private-id"}',
        stderr: "request to https://private.example.test failed",
      }),
    },
  );
  const output = formatProofReport(report);
  assert.equal(report.success, false);
  assert.equal(output.includes("secret-value"), false);
  assert.equal(output.includes("private-id"), false);
  assert.equal(output.includes("private.example.test"), false);
});

import assert from "node:assert/strict";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import test from "node:test";

const executable = fileURLToPath(new URL("../src/bin.js", import.meta.url));

test("the packaged CLI process separates help, JSON output, and errors", async (context) => {
  const configRoot = await mkdtemp(join(tmpdir(), "teamcity-cli-process-"));
  context.after(() => rm(configRoot, { recursive: true, force: true }));

  const run = (argv: readonly string[]) =>
    spawnSync(process.execPath, [executable, ...argv], {
      encoding: "utf8",
      env: { ...process.env, CLI_FACTORY_HOME: configRoot },
    });

  const root = run([]);
  assert.equal(root.status, 0, root.stderr);
  assert.match(root.stdout, /Usage: teamcity-cli/);
  assert.match(root.stdout, /projects/);
  assert.equal(root.stderr, "");

  const profileHelp = run(["profile", "--help"]);
  assert.equal(profileHelp.status, 0, profileHelp.stderr);
  for (const command of ["create", "set", "set-default", "delete"]) {
    assert.match(profileHelp.stdout, new RegExp(`\\b${command}\\b`));
  }
  assert.equal(profileHelp.stderr, "");

  const permissionHelp = run(["jobs", "run", "--help"]);
  assert.equal(permissionHelp.status, 0, permissionHelp.stderr);
  assert.match(permissionHelp.stdout, /Required permission: Update/);
  assert.equal(permissionHelp.stderr, "");

  const json = run(["permissions", "list", "--json"]);
  assert.equal(json.status, 0, json.stderr);
  assert.deepEqual(JSON.parse(json.stdout), [
    {
      name: "ReadOnly",
      enabled: true,
      description: "Read remote state without changing it",
    },
    {
      name: "Update",
      enabled: false,
      description: "Perform operations that may change remote state",
    },
  ]);
  assert.equal(json.stderr, "");

  const invalid = run(["builds", "list", "--limit", "101"]);
  assert.equal(invalid.status, 1);
  assert.equal(invalid.stdout, "");
  assert.match(invalid.stderr, /between 1 and 100/);
});

import { Readable, Writable } from "node:stream";
import {
  MemorySecretStore,
  type CliRuntime,
  type Profile,
  type ProfileStoreContract,
  type ProfileValues,
} from "@eyeauras/cli-factory";

export class TestProfileStore implements ProfileStoreContract {
  readonly #profiles = new Map<string, ProfileValues>();
  readonly #permissions = new Map<string, string[]>();
  #active: string;

  public constructor(
    profiles: Array<{
      name: string;
      url?: string;
      guest?: boolean;
      permissions?: readonly string[];
    }> = [{ name: "default", url: "https://teamcity.test" }],
  ) {
    const first = profiles[0];
    if (!first) {
      throw new Error("At least one test profile is required.");
    }
    this.#active = first.name;
    for (const profile of profiles) {
      this.#profiles.set(profile.name, {
        ...(profile.url === undefined ? {} : { url: profile.url }),
        ...(profile.guest === undefined ? {} : { guest: profile.guest }),
      });
      if (profile.permissions !== undefined) {
        this.#permissions.set(profile.name, [...profile.permissions]);
      }
    }
  }

  public async get(name = this.#active): Promise<Profile> {
    const values = this.#profiles.get(name);
    if (!values) {
      throw new Error(`Unknown test profile '${name}'.`);
    }
    return { name, values: structuredClone(values) };
  }

  public async list(): Promise<{ active: string; profiles: Profile[] }> {
    return {
      active: this.#active,
      profiles: [...this.#profiles].map(([name, values]) => ({
        name,
        values: structuredClone(values),
      })),
    };
  }

  public async create(name: string, values: ProfileValues = {}): Promise<Profile> {
    if (this.#profiles.has(name)) {
      throw new Error(`Profile '${name}' already exists.`);
    }
    this.#profiles.set(name, structuredClone(values));
    return { name, values: structuredClone(values) };
  }

  public async set(name: string, values: ProfileValues): Promise<Profile> {
    const current = this.#profiles.get(name);
    if (!current) {
      throw new Error(`Profile '${name}' does not exist.`);
    }
    const next = { ...current, ...values };
    this.#profiles.set(name, next);
    return { name, values: structuredClone(next) };
  }

  public async setDefault(name: string): Promise<Profile> {
    const profile = await this.get(name);
    this.#active = name;
    return profile;
  }

  public async delete(name: string): Promise<{ deleted: string; default: string }> {
    if (this.#profiles.size === 1) {
      throw new Error("Cannot delete the only profile.");
    }
    if (name === this.#active) {
      throw new Error("Cannot delete the default profile.");
    }
    if (!this.#profiles.delete(name)) {
      throw new Error(`Profile '${name}' does not exist.`);
    }
    this.#permissions.delete(name);
    return { deleted: name, default: this.#active };
  }

  public async getPermissions(name = this.#active): Promise<readonly string[] | undefined> {
    const permissions = this.#permissions.get(name);
    return permissions === undefined ? undefined : [...permissions];
  }

  public async setPermissions(
    name: string,
    permissions: readonly string[],
  ): Promise<readonly string[]> {
    const next = [...permissions];
    this.#permissions.set(name, next);
    return next;
  }
}

export interface TestRuntime {
  runtime: CliRuntime;
  profileStore: TestProfileStore;
  secretStore: MemorySecretStore;
  stdout(): string;
  stderr(): string;
  resetOutput(): void;
}

export async function createTestRuntime(options: {
  profiles?: Array<{
    name: string;
    url?: string;
    guest?: boolean;
    permissions?: readonly string[];
  }>;
  tokens?: Record<string, string>;
  input?: string;
} = {}): Promise<TestRuntime> {
  const profileStore = new TestProfileStore(options.profiles);
  const secretStore = new MemorySecretStore();
  for (const [profile, token] of Object.entries(options.tokens ?? { default: "fixture-token" })) {
    await secretStore.set("ai-cli-factory:teamcity-cli", `${profile}:token`, token);
  }
  let stdout = "";
  let stderr = "";
  const output = new Writable({
    write(chunk, _encoding, callback) {
      stdout += chunk.toString();
      callback();
    },
  });
  const error = new Writable({
    write(chunk, _encoding, callback) {
      stderr += chunk.toString();
      callback();
    },
  });
  return {
    runtime: {
      input: Readable.from([options.input ?? ""]),
      output,
      error,
      profileStore,
      secretStore,
    },
    profileStore,
    secretStore,
    stdout: () => stdout,
    stderr: () => stderr,
    resetOutput() {
      stdout = "";
      stderr = "";
    },
  };
}

import { execFile } from "node:child_process";
import { resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { promisify } from "node:util";

const executeFile = promisify(execFile);
const cliPath = fileURLToPath(new URL("../src/bin.js", import.meta.url));
type Invoker = (argv: readonly string[]) => Promise<string>;
type Endpoint =
  | "GET /api/users/me"
  | "GET /api/admin/projects"
  | "GET /api/issues"
  | "GET /api/issues/{issueID}"
  | "GET /api/issues/{issueID}/comments";
interface ProofRow {
  endpoint: Endpoint;
  status: "PASS" | "FAIL" | "SKIP";
  count: number;
}
interface ProofResult {
  passed: boolean;
  rows: ProofRow[];
}

export function proofEnvironment(environment: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  return Object.fromEntries(
    Object.entries(environment).filter(([name]) => name.toUpperCase() !== "YOUTRACK_TOKEN"),
  );
}

async function invokeCli(argv: readonly string[]): Promise<string> {
  const result = await executeFile(process.execPath, [cliPath, ...argv], {
    windowsHide: true,
    timeout: 30_000,
    maxBuffer: 64 * 1024,
    encoding: "utf8",
    env: proofEnvironment(process.env),
  });
  return result.stdout;
}

function hasId(value: unknown): value is { id: string } {
  return value !== null && typeof value === "object" && !Array.isArray(value) &&
    "id" in value && typeof value.id === "string" && value.id.trim().length > 0 &&
    value.id.length <= 256 && !value.id.startsWith("-") && !/[\u0000-\u001f\u007f]/.test(value.id);
}

function isCollection(value: unknown): value is { id: string }[] {
  return Array.isArray(value) && value.length <= 3 && value.every(hasId);
}

export async function runProfileProof(
  argv: readonly string[],
  environment: NodeJS.ProcessEnv = process.env,
  invoke: Invoker = invokeCli,
): Promise<ProofResult> {
  const ciNames = ["CI", "GITHUB_ACTIONS", "TF_BUILD", "TEAMCITY_VERSION", "JENKINS_URL", "BUILDKITE"];
  if (Object.entries(environment).some(([name, value]) => value && ciNames.includes(name.toUpperCase()))) {
    throw new Error("YouTrack profile proof is local-only and refuses CI.");
  }
  const profile = argv[1];
  if (argv.length !== 2 || argv[0] !== "--profile" || !profile ||
      !/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(profile) ||
      profile.toLowerCase() === "profiles.json") {
    throw new Error("Usage: test:integration -- --profile <name>");
  }

  const commonArgs = ["--profile", profile, "--json"];
  const rows: ProofRow[] = [];
  async function read(
    endpoint: Endpoint,
    command: readonly string[],
    valid: (value: unknown) => boolean,
  ): Promise<unknown> {
    try {
      const value: unknown = JSON.parse(await invoke([...command, ...commonArgs]));
      if (valid(value)) {
        rows.push({ endpoint, status: "PASS", count: Array.isArray(value) ? value.length : 1 });
        return value;
      }
    } catch {
      // Child errors can contain payloads, stderr, URLs or credentials. Never render them.
    }
    rows.push({ endpoint, status: "FAIL", count: 0 });
    return undefined;
  }

  await read("GET /api/users/me", ["user", "me"], (value) =>
    hasId(value) && "login" in value && typeof value.login === "string" && value.login.trim().length > 0);
  const page = ["--top", "3", "--skip", "0", "--fields", "id"];
  await read("GET /api/admin/projects", ["project", "list", "--top", "3", "--skip", "0"],
    (value) => isCollection(value) && value.every((project) =>
      "name" in project && typeof project.name === "string" &&
      "shortName" in project && typeof project.shortName === "string"));
  const issues = await read("GET /api/issues", ["issues", "list", ...page], isCollection);
  const issueId = isCollection(issues) ? issues[0]?.id : undefined;
  if (issueId !== undefined) {
    await read("GET /api/issues/{issueID}", ["issues", "get", issueId, "--fields", "id"],
      (value) => hasId(value) && value.id === issueId);
    await read("GET /api/issues/{issueID}/comments",
      ["issues", "comments", "list", issueId, ...page], isCollection);
  } else {
    rows.push(
      { endpoint: "GET /api/issues/{issueID}", status: "SKIP", count: 0 },
      { endpoint: "GET /api/issues/{issueID}/comments", status: "SKIP", count: 0 },
    );
  }
  return { passed: rows.every((row) => row.status !== "FAIL"), rows };
}

export function formatProfileProof(result: ProofResult): string {
  return result.rows.map((row) => `${row.status} ${row.endpoint}: ${row.count} records\n`).join("");
}

const entryUrl = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : undefined;
if (entryUrl === import.meta.url) {
  try {
    const result = await runProfileProof(process.argv.slice(2));
    process.stdout.write(formatProfileProof(result));
    process.exitCode = result.passed ? 0 : 1;
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : "Proof refused."}\n`);
    process.exitCode = 2;
  }
}

#!/usr/bin/env node
import { createYouTrackCli } from "./cli.js";

process.exitCode = await createYouTrackCli().run();

import type { CommandContext, OptionDefinition } from "@eyeauras/cli-factory";
import { youTrackUrl, type Connection, type IssueSearchOptions } from "./client.js";

export const bodyOptions: readonly OptionDefinition[] = [
  {
    flags: "--body <json>",
    description: "Required JSON object containing this command's supported fields",
    required: true,
    parse: parseBody,
  },
];

export function parseBody(value: string): unknown {
  try {
    return JSON.parse(value) as unknown;
  } catch {
    throw new Error("YouTrack body must be valid JSON.");
  }
}

export const projectionOptions: readonly OptionDefinition[] = [
  { flags: "--fields <projection>", description: "Explicit YouTrack fields projection" },
];
export const pageOptions: readonly OptionDefinition[] = [
  ...projectionOptions,
  { flags: "--top <count>", description: "Maximum results (1-100)", defaultValue: 50, parse: integer },
  { flags: "--skip <offset>", description: "Nonnegative result offset", defaultValue: 0, parse: integer },
];

export function integer(value: string): number {
  if (!/^\d+$/.test(value)) {
    throw new Error("YouTrack paging values must be decimal integers.");
  }
  return Number(value);
}

export async function connection(context: CommandContext): Promise<Connection> {
  const baseUrl = youTrackUrl(context.profile.values.url);
  return {
    baseUrl,
    token: await context.secrets.require("token"),
    fetch: context.fetch,
    signal: context.signal,
  };
}

export function readOptions(options: Record<string, unknown>): IssueSearchOptions {
  return {
    ...(typeof options.fields === "string" ? { fields: options.fields } : {}),
    ...(typeof options.top === "number" ? { top: options.top } : {}),
    ...(typeof options.skip === "number" ? { skip: options.skip } : {}),
    ...(typeof options.query === "string" ? { query: options.query } : {}),
  };
}

import {
  command,
  createCli,
  Permission,
  tokenAuth,
  type CliApplication,
  type CliRuntime,
} from "@eyeauras/cli-factory";
import {
  addComment,
  createIssue,
  currentUser,
  getIssue,
  listComments,
  listIssues,
  listProjects,
  readUser,
  updateIssue,
  youTrackUrl,
} from "./client.js";
import { bodyOptions, connection, pageOptions, projectionOptions, readOptions } from "./cli-support.js";

export function createYouTrackCli(runtime?: CliRuntime): CliApplication {
  return createCli({
    name: "youtrack-cli",
    description: "AI-friendly access to YouTrack",
    version: "0.1.0",
    applicationId: "youtrack-cli",
    permissions: {},
    profile: {
      fields: [
        {
          name: "url",
          flags: "--url <url>",
          description: "YouTrack server URL including any context path, without /api",
          required: true,
        },
      ],
      validate(values) {
        if (values.url !== undefined) {
          youTrackUrl(values.url);
        }
      },
    },
    auth: tokenAuth({
      env: "YOUTRACK_TOKEN",
      validate: ({ profile, token, fetch, signal }) => currentUser({
        baseUrl: youTrackUrl(profile.values.url),
        token,
        fetch,
        signal,
      }),
    }),
    commands: [
      command("user", "Inspect the current YouTrack user", [
        command(
          "me",
          "Show the authenticated user (default: ID and login)",
          async ({ options }, context) => readUser(await connection(context), readOptions(options)),
          { permission: Permission.ReadOnly, options: projectionOptions },
        ),
      ]),
      command("project", "Inspect YouTrack projects", [
        command(
          "list",
          "List one page of projects",
          async ({ options }, context) => listProjects(await connection(context), readOptions(options)),
          { permission: Permission.ReadOnly, options: pageOptions },
        ),
      ]),
      command("issues", "Read and update YouTrack issues", [
        command(
          "create",
          "Create an issue with project.id, summary and optional description",
          async ({ options }, context) =>
            createIssue(await connection(context), options.body),
          { permission: Permission.Update, options: bodyOptions },
        ),
        command(
          "update <issueID>",
          "Update summary and/or description; description null clears it",
          async ({ args, options }, context) =>
            updateIssue(await connection(context), String(args.issueID), options.body),
          { permission: Permission.Update, options: bodyOptions },
        ),
        command(
          "list",
          "Search one page of issues using YouTrack query syntax",
          async ({ options }, context) => listIssues(await connection(context), readOptions(options)),
          {
            permission: Permission.ReadOnly,
            options: [
              ...pageOptions,
              { flags: "--query <query>", description: "YouTrack search query" },
            ],
          },
        ),
        command(
          "get <issueID>",
          "Show an issue by database or readable ID",
          async ({ args, options }, context) =>
            getIssue(await connection(context), String(args.issueID), readOptions(options)),
          { permission: Permission.ReadOnly, options: projectionOptions },
        ),
        command("comments", "Read and add issue comments", [
          command(
            "add <issueID>",
            "Add a comment with a nonempty text field",
            async ({ args, options }, context) =>
              addComment(await connection(context), String(args.issueID), options.body),
            { permission: Permission.Update, options: bodyOptions },
          ),
          command(
            "list <issueID>",
            "List one page of comments for an issue",
            async ({ args, options }, context) =>
              listComments(await connection(context), String(args.issueID), readOptions(options)),
            { permission: Permission.ReadOnly, options: pageOptions },
          ),
        ]),
      ]),
    ],
    ...(runtime === undefined ? {} : { runtime }),
  });
}

export interface YouTrackUser {
  id: string;
  login: string;
}

export interface Connection {
  baseUrl: string;
  token: string;
  fetch?: typeof globalThis.fetch;
  signal?: AbortSignal;
}

export function youTrackUrl(value: unknown): string {
  const message =
    "YouTrack URL must be an HTTPS server URL with an optional context path, " +
    "without credentials, query, fragment or appended /api (HTTP is allowed only on localhost).";
  if (typeof value !== "string" || /[\\\u0000-\u0020\u007f]/.test(value.trim())) {
    throw new Error(message);
  }
  let url: URL;
  try {
    url = new URL(value.trim());
  } catch {
    throw new Error(message);
  }
  const localhost = ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname);
  let pathname: string;
  try {
    pathname = decodeURIComponent(url.pathname).replace(/\/+$/, "");
  } catch {
    throw new Error(message);
  }
  if (
    (url.protocol !== "https:" && !(url.protocol === "http:" && localhost)) ||
    url.username || url.password || url.search || url.hash || /\/api$/i.test(pathname) ||
    value.includes("?") || value.includes("#")
  ) {
    throw new Error(message);
  }
  url.pathname = url.pathname.replace(/\/+$/, "") + "/";
  return url.href;
}

export type YouTrackValue = null | boolean | number | string | YouTrackObject | YouTrackValue[];
export interface YouTrackObject {
  [field: string]: YouTrackValue;
}
export interface ProjectionOptions {
  fields?: string;
}
export interface PageOptions extends ProjectionOptions {
  top?: number;
  skip?: number;
}
export interface IssueSearchOptions extends PageOptions {
  query?: string;
}

const issueListFields = "id,idReadable,summary,project(id,name,shortName),updated,resolved";
const commentFields = "id,text,author(id,login),created,updated";

export function requiredText(value: string, label: string): string {
  if (!value.trim() || /[\u0000-\u001f\u007f]/.test(value)) {
    throw new Error(`YouTrack ${label} must be nonempty text without control characters.`);
  }
  return value;
}

export function fields(options: ProjectionOptions, defaults: string): string {
  return requiredText(options.fields ?? defaults, "fields");
}

export function page(options: PageOptions, defaults: string): Record<string, string> {
  const top = options.top ?? 50;
  const skip = options.skip ?? 0;
  if (!Number.isSafeInteger(top) || top < 1 || top > 100) {
    throw new Error("YouTrack top must be an integer between 1 and 100.");
  }
  if (!Number.isSafeInteger(skip) || skip < 0) {
    throw new Error("YouTrack skip must be a nonnegative safe integer.");
  }
  return { fields: fields(options, defaults), $top: String(top), $skip: String(skip) };
}

export function encodedID(id: string, label = "ID"): string {
  requiredText(id, label);
  if (id === "." || id === "..") {
    throw new Error(`YouTrack ${label} must not be a dot path segment.`);
  }
  try {
    return encodeURIComponent(id);
  } catch {
    throw new Error(`YouTrack ${label} must contain valid Unicode text.`);
  }
}

export function issuePath(id: string): string {
  return `api/issues/${encodedID(id, "issue ID")}`;
}

function scrubUrl(text: string): string {
  try {
    const url = new URL(text, "https://youtrack.example.com");
    const signedPath = /(?:^|\/)(?:sign|signature|token)=/i.test(decodeURIComponent(url.pathname));
    const keys = [...url.searchParams.keys(), ...new URLSearchParams(url.hash.slice(1)).keys()];
    const credentialQuery = keys.some((key) => [
      "sign", "sig", "signature", "token", "accesstoken", "refreshtoken", "idtoken",
      "secret", "password", "credential", "credentials", "auth", "authorization", "authtoken",
      "apikey", "key", "awsaccesskeyid", "xamzsignature", "xamzcredential", "xamzsecuritytoken",
      "xgoogsignature", "xgoogcredential",
    ].includes(key.replace(/[-_]/g, "").toLowerCase()));
    return url.username || url.password || signedPath || credentialQuery ? "[redacted]" : text;
  } catch {
    return "[redacted]";
  }
}

function scrub(value: YouTrackValue, token: string): YouTrackValue {
  if (typeof value === "string") {
    const text = value.replaceAll(token, "[redacted]");
    if (!/\s/.test(text) && /[\/?#]/.test(text) && scrubUrl(text) === "[redacted]") {
      return "[redacted]";
    }
    return text.replace(/(?:https?:\/\/|\.\.?\/|\/)[^\s"'<>]+/gi, scrubUrl);
  }
  if (Array.isArray(value)) {
    return value.map((item) => scrub(item, token));
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [
      key.replaceAll(token, "[redacted]"), scrub(item, token),
    ]));
  }
  return value;
}
function object(value: YouTrackValue): YouTrackObject {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("YouTrack returned an invalid object response.");
  }
  return value;
}

async function request(
  connection: Connection,
  path: string,
  query: Record<string, string>,
  responseName = "JSON",
  body?: YouTrackObject,
): Promise<YouTrackValue> {
  const url = new URL(path, youTrackUrl(connection.baseUrl));
  url.search = new URLSearchParams(query).toString();
  const token = connection.token.trim();
  if (!token || /[\r\n]/.test(token)) {
    throw new Error("YouTrack authentication requires a non-empty single-line token.");
  }
  let response: Response;
  try {
    response = await (connection.fetch ?? globalThis.fetch)(url, {
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
        ...(body === undefined ? {} : { "Content-Type": "application/json" }),
      },
      ...(body === undefined ? {} : { method: "POST", body: JSON.stringify(body) }),
      redirect: "error",
      ...(connection.signal === undefined ? {} : { signal: connection.signal }),
    });
  } catch {
    throw new Error("YouTrack request failed; check connectivity, TLS and the configured URL.");
  }
  if (!response.ok) {
    const retryAfter = response.headers.get("retry-after");
    let retry = "";
    if (response.status === 429 && retryAfter) {
      if (/^\d{1,10}$/.test(retryAfter)) {
        retry = ` Retry after ${Number(retryAfter)} seconds.`;
      } else if (/^[A-Z][a-z]{2}, \d{2} [A-Z][a-z]{2} \d{4} \d{2}:\d{2}:\d{2} GMT$/.test(retryAfter)) {
        const date = new Date(retryAfter);
        if (!Number.isNaN(date.getTime())) {
          retry = ` Retry after ${date.toUTCString()}.`;
        }
      }
    }
    throw new Error(`YouTrack request failed (HTTP ${response.status}).${retry}`);
  }
  let value: YouTrackValue;
  try {
    const text = await response.text();
    if (body !== undefined && !text.trim()) {
      return null;
    }
    value = JSON.parse(text) as YouTrackValue;
  } catch {
    throw new Error(`YouTrack returned an invalid ${responseName} response.`);
  }
  if (body !== undefined && value === null) {
    throw new Error("YouTrack returned an invalid mutation response.");
  }
  return value;
}

export async function readObject(
  connection: Connection,
  path: string,
  query: Record<string, string>,
): Promise<YouTrackObject> {
  return object(scrub(await request(connection, path, query), connection.token.trim()));
}

export async function readCollection(
  connection: Connection,
  path: string,
  query: Record<string, string>,
): Promise<YouTrackObject[]> {
  const value = scrub(await request(connection, path, query), connection.token.trim());
  if (!Array.isArray(value)) {
    throw new Error("YouTrack returned an invalid collection response.");
  }
  if (value.length > Number(query.$top)) {
    throw new Error("YouTrack returned more items than the requested top limit.");
  }
  return value.map(object);
}

export async function currentUser(connection: Connection): Promise<YouTrackUser> {
  const value = await request(connection, "api/users/me", { fields: "id,login" }, "identity");
  const token = connection.token.trim();
  if (
    value === null || typeof value !== "object" ||
    !("id" in value) || typeof value.id !== "string" || !value.id.trim() ||
    !("login" in value) || typeof value.login !== "string" || !value.login.trim() ||
    value.id.includes(token) || value.login.includes(token)
  ) {
    throw new Error("YouTrack returned an invalid identity response.");
  }
  return { id: value.id, login: value.login };
}

export async function readUser(
  connection: Connection,
  options: ProjectionOptions = {},
): Promise<YouTrackUser | YouTrackObject> {
  return options.fields === undefined
    ? currentUser(connection)
    : readObject(connection, "api/users/me", { fields: fields(options, "id,login") });
}

export async function listProjects(
  connection: Connection,
  options: PageOptions = {},
): Promise<YouTrackObject[]> {
  return readCollection(connection, "api/admin/projects", page(options, "id,name,shortName"));
}

export async function listIssues(
  connection: Connection,
  options: IssueSearchOptions = {},
): Promise<YouTrackObject[]> {
  return readCollection(connection, "api/issues", {
    ...page(options, issueListFields),
    ...(options.query === undefined ? {} : { query: requiredText(options.query, "query") }),
  });
}

export async function getIssue(
  connection: Connection,
  id: string,
  options: ProjectionOptions = {},
): Promise<YouTrackObject> {
  return readObject(connection, issuePath(id), {
    fields: fields(options, `${issueListFields},description,created`),
  });
}

export async function listComments(
  connection: Connection,
  issueID: string,
  options: PageOptions = {},
): Promise<YouTrackObject[]> {
  return readCollection(connection, `${issuePath(issueID)}/comments`, page(options, commentFields));
}

export function mutationBody(value: unknown, allowed: readonly string[]): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value) ||
      ![Object.prototype, null].includes(Object.getPrototypeOf(value))) {
    throw new Error("YouTrack body must be a JSON object.");
  }
  if (Object.keys(value).some((key) => !allowed.includes(key))) {
    throw new Error(`This YouTrack slice supports only these body fields: ${allowed.join(", ")}.`);
  }
  return value as Record<string, unknown>;
}

export function narrative(value: unknown, label: string): string {
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`YouTrack ${label} must be nonempty text.`);
  }
  return value;
}

function description(value: unknown): string | null {
  if (value !== null && typeof value !== "string") {
    throw new Error("YouTrack description must be text or null.");
  }
  return value;
}

export async function mutate(
  connection: Connection,
  path: string,
  body: YouTrackObject,
  projection: string,
): Promise<YouTrackObject | null> {
  const value = await request(connection, path, { fields: projection }, "JSON", body);
  return value === null ? null : object(scrub(value, connection.token.trim()));
}

export async function createIssue(
  connection: Connection,
  input: unknown,
): Promise<YouTrackObject | null> {
  const body = mutationBody(input, ["project", "summary", "description"]);
  const project = mutationBody(body.project, ["id"]);
  return mutate(connection, "api/issues", {
    project: { id: narrative(project.id, "project.id") },
    summary: narrative(body.summary, "summary"),
    ...(Object.hasOwn(body, "description") ? { description: description(body.description) } : {}),
  }, "id,idReadable,summary,updated");
}

export async function updateIssue(
  connection: Connection,
  id: string,
  input: unknown,
): Promise<YouTrackObject | null> {
  const body = mutationBody(input, ["summary", "description"]);
  if (Object.keys(body).length === 0) {
    throw new Error("YouTrack issue update requires summary or description.");
  }
  return mutate(connection, issuePath(id), {
    ...(Object.hasOwn(body, "summary") ? { summary: narrative(body.summary, "summary") } : {}),
    ...(Object.hasOwn(body, "description") ? { description: description(body.description) } : {}),
  }, "id,idReadable,summary,updated");
}

export async function addComment(
  connection: Connection,
  issueID: string,
  input: unknown,
): Promise<YouTrackObject | null> {
  const body = mutationBody(input, ["text"]);
  return mutate(connection, `${issuePath(issueID)}/comments`, {
    text: narrative(body.text, "text"),
  }, commentFields);
}

import assert from "node:assert/strict";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Readable, Writable } from "node:stream";
import { after, afterEach, before, test, type TestContext } from "node:test";
import { AppArguments, MemorySecretStore } from "@eyeauras/cli-factory";
import { http, HttpResponse } from "msw";
import { setupServer } from "msw/node";
import { createYouTrackCli } from "../src/cli.js";

const server = setupServer();
before(() => server.listen({ onUnhandledRequest: "error" }));
afterEach(() => server.resetHandlers());
after(() => server.close());
const service = "ai-cli-factory:youtrack-cli";
const identity = { id: "1-1", login: "fixture-user" };

async function fixture(t: TestContext, input = "") {
  const directory = await mkdtemp(join(tmpdir(), "youtrack-auth-test-"));
  t.after(async () => { await rm(directory, { recursive: true, force: true }); });
  const appArguments = new AppArguments({ AppName: "youtrack-cli", Environment: {
    AppDomainDirectory: join(directory, "executable"),
    ApplicationExecutablePath: join(directory, "executable", "youtrack-cli.js"),
    EnvironmentAppData: join(directory, "roaming"),
    EnvironmentLocalAppData: join(directory, "local"),
    ProcessId: 1,
  } });
  const paths: string[] = [];
  const withProfile = appArguments.WithProfile.bind(appArguments);
  appArguments.WithProfile = (name) => {
    const scoped = withProfile(name);
    paths.push(scoped.AppDataDirectory);
    return scoped;
  };
  const secrets = new MemorySecretStore();
  let stdout = "";
  let stderr = "";
  const runtime = {
    appArguments, secretStore: secrets, input: Readable.from([input]),
    output: new Writable({ write(chunk, _encoding, done) { stdout += chunk.toString(); done(); } }),
    error: new Writable({ write(chunk, _encoding, done) { stderr += chunk.toString(); done(); } }),
  };
  const cli = createYouTrackCli(runtime);
  return { cli, runtime, secrets, appArguments, paths, stdout: () => stdout, stderr: () => stderr };
}

test("fresh configure validates before keyring storage and keeps config non-secret", async (t) => {
  const f = await fixture(t, "synthetic-candidate\n");
  server.use(http.get("https://youtrack.example.com/track/api/users/me", async ({ request }) => {
    assert.equal(await f.secrets.get(service, "dev:token"), undefined);
    assert.equal(request.headers.get("authorization"), "Bearer synthetic-candidate");
    assert.equal(new URL(request.url).searchParams.get("fields"), "id,login");
    return HttpResponse.json(identity);
  }));
  assert.equal(await f.cli.run(["profile", "configure", "dev", "--url", "https://youtrack.example.com/track", "--token-stdin", "--json"]), 0);
  assert.equal(await f.secrets.get(service, "dev:token"), "synthetic-candidate");
  assert.deepEqual(JSON.parse(f.stdout()).identity, identity);
  assert.ok(!f.stdout().includes("synthetic-candidate"));
  const config = await readFile(join(f.appArguments.RoamingAppDataDirectory, "profiles.json"), "utf8");
  assert.ok(!config.includes("synthetic-candidate"));
  assert.ok(f.paths.includes(join(f.appArguments.RoamingAppDataDirectory, "dev")));
});

test("rejected candidates do not replace credentials and errors reveal no server payload", async (t) => {
  const f = await fixture(t, "synthetic-rejected\n");
  await f.cli.execute(["profile", "create", "dev", "--url", "https://youtrack.example.com"]);
  await f.secrets.set(service, "dev:token", "synthetic-existing");
  server.use(http.get("*/api/users/me", () => new HttpResponse("synthetic-rejected private-data", { status: 401 })));
  assert.equal(await f.cli.run(["auth", "login", "--profile", "dev", "--token-stdin", "--json"]), 1);
  assert.equal(await f.secrets.get(service, "dev:token"), "synthetic-existing");
  assert.equal(f.stdout(), "");
  assert.match(f.stderr(), /HTTP 401/);
  assert.doesNotMatch(f.stderr(), /synthetic-|private-data/);
});

test("invalid configuration is rejected before reading or writing keyring", async (t) => {
  const f = await fixture(t, "synthetic-candidate\n");
  f.secrets.get = async () => { assert.fail("Invalid URL reached keyring"); };
  f.secrets.set = async () => { assert.fail("Invalid URL reached keyring"); };
  assert.equal(await f.cli.run(["profile", "configure", "dev", "--url", "http://youtrack.example.com", "--token-stdin"]), 1);
  assert.match(f.stderr(), /YouTrack URL must/);
});

test("noninteractive unconfigured identity fails actionably before network", async (t) => {
  const f = await fixture(t);
  assert.equal(await f.cli.run(["user", "me", "--json"]), 1);
  assert.equal(f.stdout(), "");
  assert.match(f.stderr(), /youtrack-cli profile configure default --url <url>/);
  await assert.rejects(f.cli.execute(["user", "me"]), /profile configure/);
});

test("profile credentials, URLs, permissions and logout remain isolated", async (t) => {
  const f = await fixture(t);
  for (const name of ["dev", "production"]) {
    await f.cli.execute(["profile", "create", name, "--url", `https://${name}.example.com/track`]);
    await f.secrets.set(service, `${name}:token`, `synthetic-${name}`);
  }
  let calls = 0;
  server.use(http.get("*/api/users/me", ({ request }) => {
    calls++;
    const name = new URL(request.url).hostname.split(".")[0];
    assert.equal(request.headers.get("authorization"), `Bearer synthetic-${name}`);
    return HttpResponse.json({ id: `fixture-${name}`, login: `user-${name}` });
  }));
  await f.cli.execute(["permissions", "grant", "Update", "--profile", "dev"]);
  const productionPermissions = await f.cli.execute(["permissions", "list", "--profile", "production"]);
  assert.ok(Array.isArray(productionPermissions));
  assert.equal(productionPermissions.find((p) => p.name === "Update")?.enabled, false);
  for (const name of ["dev", "production"])
    assert.deepEqual(await f.cli.execute(["user", "me", "--profile", name]), { id: `fixture-${name}`, login: `user-${name}` });
  assert.equal(calls, 2);
  await f.cli.execute(["permissions", "revoke", "ReadOnly", "--profile", "dev"]);
  await assert.rejects(f.cli.execute(["user", "me", "--profile", "dev"]), /Permission 'ReadOnly' is disabled/);
  assert.equal(calls, 2);
  await f.cli.execute(["auth", "logout", "--profile", "dev"]);
  assert.equal(await f.secrets.get(service, "dev:token"), undefined);
  assert.equal(await f.secrets.get(service, "production:token"), "synthetic-production");
});

test("persistent RPC uses the actual declaration with profile-specific identity and AppData", async (t) => {
  const requests = ["dev", "production", "dev"].map((name, id) => JSON.stringify({
    jsonrpc: "2.0", id, method: "cli.execute", params: { argv: ["user", "me", "--profile", name] },
  })).join("\n") + "\n";
  const f = await fixture(t, requests);
  for (const name of ["dev", "production"]) {
    await f.cli.execute(["profile", "create", name, "--url", `https://${name}.example.com`]);
    await f.secrets.set(service, `${name}:token`, `synthetic-${name}`);
  }
  server.use(http.get("*/api/users/me", ({ request }) => {
    const name = new URL(request.url).hostname.split(".")[0];
    assert.equal(request.headers.get("authorization"), `Bearer synthetic-${name}`);
    return HttpResponse.json({ id: `fixture-${name}`, login: `user-${name}` });
  }));
  f.paths.length = 0;
  assert.equal(await f.cli.run(["--json-rpc"]), 0);
  const replies = f.stdout().trim().split("\n").map((line) => JSON.parse(line));
  assert.deepEqual(replies.map((reply) => reply.result.login), ["user-dev", "user-production", "user-dev"]);
  assert.deepEqual(f.paths, ["dev", "production", "dev"].map((name) => join(f.appArguments.RoamingAppDataDirectory, name)));
  assert.equal(f.stderr(), "");
});


test("keyring write failure never falls back to files or exposes the candidate", async (t) => {
  const f = await fixture(t, "synthetic-candidate\n");
  server.use(http.get("*/api/users/me", () => HttpResponse.json(identity)));
  f.secrets.set = async () => { throw new Error("OS credential store unavailable."); };
  assert.equal(await f.cli.run(["profile", "configure", "dev", "--url", "https://youtrack.example.com", "--token-stdin", "--json"]), 1);
  assert.equal(await f.secrets.get(service, "dev:token"), undefined);
  assert.equal(f.stdout(), "");
